interface SchoolAccount {String summary();} class StudentAccount implements SchoolAccount {public String summary(){return "Student account";}} class TeacherAccount implements SchoolAccount {public String summary(){return "Teacher account";}} class SchoolAccountFactory {static SchoolAccount create(String type){if("student".equalsIgnoreCase(type))return new StudentAccount();if("teacher".equalsIgnoreCase(type))return new TeacherAccount();throw new IllegalArgumentException("Unknown account type: "+type);}}
public class SchoolFactoryPatternDemo { public static void main(String[] args){System.out.println(SchoolAccountFactory.create("student").summary());System.out.println(SchoolAccountFactory.create("teacher").summary());System.out.println("Factory pattern keeps object creation in one place.");} }
